{ name: 'Shipshewana North Park Campground', where: '5970 N SR 5 · Shipshewana, IN', city: 'Shipshewana (Indiana Amish Country), IN', phone: '(260) 768-7770', tag: 'Campground', facts: ['Pets allowed; call for rules', 'Full hookups, 30/50 amp; pull-thru sites', 'No published max RV length; confirm at booking'], note: 'Next to SR 5 and Hwy 120, so truck noise starts early. Ask for a site away from the road.', source: 'Biscuit researched this', zip: '46565', lat: 41.691, lng: -85.584 }
