{ name: 'Bass River State Forest', where: 'New Jersey', city: 'New Gretna, NJ', phone: '(609) 296-1114', tag: 'State Park', facts: ['No hookups, dump station on-site', 'Dogs allowed, registration required'], note: 'Designated pet-friendly campsites (1-85), $5/night pet fee. New Jersey\'s oldest state forest. No published max RV length; confirm at booking.', source: 'Biscuit researched this', zip: '08224', lat: 39.599, lng: -74.467 },
{ name: 'Wharton State Forest – Atsion Family Campground', where: 'Atsion Recreation Area, Rt. 206, Shamong Township (Wharton State Forest), NJ', city: 'Wharton State Forest / Pine Barrens, NJ', phone: '(609) 268-0444', tag: 'State Park', facts: ['Pet-friendly sites 26–34 only', '+$5/night pet fee', '40-ft RV length limit'], note: 'Real Pine Barrens camping, so pups need to stick to the designated pet-friendly loop rather than the lakefront sites. Check in early at the Atsion office, which closes at 4pm.', source: 'Biscuit researched this', zip: '08088', lat: 39.837, lng: -74.695 },
{ name: 'Bass River State Forest Campground', where: '762 Stage Rd, Tuckerton (New Gretna), NJ 08087', city: 'Wharton State Forest / Pine Barrens, NJ', phone: '(609) 296-1114', tag: 'State Park', facts: ['Tent, trailer & lean-to sites, cabins too', 'Dogs on 6-ft leash max', 'Not allowed on swim beach'], note: 'One of NJ\'s oldest state forests and a favorite Pine Barrens basecamp — your dog needs to sit the lake swim area out, but is welcome in designated camping areas on leash.', source: 'Biscuit researched this', zip: '08087', lat: 39.604, lng: -74.382 },
{ name: 'Timberline Lake Camping Resort', where: '365 Route 679, New Gretna, NJ 08224', city: 'Wharton State Forest / Pine Barrens, NJ', phone: '(609) 296-7900', tag: 'RV Park', facts: ['Full hookup pull-thru sites (up to 44 ft)', 'Minutes from Garden State Parkway', 'Rabies proof required at check-in'], note: 'A well-run, RV-friendly resort tucked in the Pine Barrens right off the Parkway, an easy overnight stop road-tripping the Jersey Shore corridor. They\'ll ask for current vaccination proof at registration.', source: 'Biscuit researched this', zip: '08224', lat: 39.599, lng: -74.467 },
{ name: 'Sun Outdoors Cape May', where: '491 US-9 · Cape May, NJ', city: 'Cape May, NJ', phone: '(609) 886-1234', tag: 'RV Resort', facts: ['Full hookups, 20/30/50 amp', 'Sites for rigs up to 35, 40 or 45ft', 'Max 2 pets; open mid-April – Nov 1'], note: 'Formerly Holly Shores. Family resort about 10 minutes from Cape May\'s beaches. Leashed pets only, and don\'t leave them alone outside.', source: 'Biscuit researched this', zip: '08204', lat: 38.972, lng: -74.916 },
{ name: 'Belleplain State Forest', where: '1 Henkinsifkin Rd · Woodbine, NJ', city: 'Cape May, NJ', phone: '(609) 861-2404', tag: 'State Park', facts: ['No published max RV length; confirm at booking', '169 tent & trailer sites, dump station (Mar–Nov)'], note: 'Wooded state forest campground on Lake Nummy, about 30 minutes from Cape May. Pets are allowed at regular campsites, but not at group sites, lean-tos or the cabin.', source: 'Biscuit researched this', zip: '08270', lat: 39.261, lng: -74.809 }
